<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import{storeToRefs}from'pinia';import InventorySubnav from '../components/InventorySubnav.vue';import InventoryScenarioBar from '../components/InventoryScenarioBar.vue';import{useInventoryStore}from'../runtime/inventory-store';import'./inventory-views.css';const store=useInventoryStore();const{workspace,loading,error,scenario,actor}=storeToRefs(store);const keyword=ref('');const warehouse=ref('');const status=ref('');const rows=computed(()=>workspace.value.batches.filter(x=>!warehouse.value||x.warehouse.id===warehouse.value).filter(x=>!status.value||x.status===status.value).filter(x=>!keyword.value||[x.batch.batchNumber,x.sku?.skuCode,x.sku?.productName].some(v=>v?.toLocaleLowerCase().includes(keyword.value.toLocaleLowerCase()))));const q=(n:number)=>`${(n/1000).toLocaleString('zh-CN',{maximumFractionDigits:3})}`;const money=(n:number)=>`¥${(n/100).toFixed(2)}`;onMounted(()=>store.load())
</script>
<template><section class="inventory-page"><header class="inventory-header"><div><h1>批次库存</h1><p>按仓库、库位、SKU 和批次追踪数量及临期边界。</p></div><InventoryScenarioBar :scenario="scenario" :role="actor.role" @scenario="store.setScenario" @role="store.setRole"/></header><InventorySubnav/><div class="inventory-panel inventory-filter"><label>仓库<select v-model="warehouse"><option value="">全部</option><option v-for="x in workspace.warehouses" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label>批次状态<select v-model="status"><option value="">全部</option><option value="normal">正常</option><option value="near-expiry">临期</option><option value="expired">过期</option></select></label><label class="keyword">关键词<input v-model="keyword" placeholder="商品 / SKU / 批次号"></label></div><div v-if="error" class="inventory-state error">{{error}}<button class="inv-button" @click="store.load">重试</button></div><div v-else-if="loading" class="inventory-state">正在加载批次…</div><div v-else-if="!rows.length" class="inventory-state">暂无批次库存</div><div v-else class="inventory-table-wrap" style="margin-top:12px"><table class="inventory-table"><thead><tr><th>仓库 / 库位</th><th>商品 / SKU</th><th>批次号</th><th>生产日期</th><th>有效期</th><th>入库时间</th><th>状态</th><th class="quantity">批次数量</th><th class="money">成本金额</th></tr></thead><tbody><tr v-for="row in rows" :key="row.batch.id+row.location.id"><td>{{row.warehouse.name}}<small>{{row.location.name}}</small></td><td>{{row.sku?.productName??'商品资料不可用'}}<small>{{row.sku?.skuCode??row.batch.skuId}}</small></td><td>{{row.batch.batchNumber}}</td><td>{{row.batch.productionDate??'—'}}</td><td>{{row.batch.expiresOn??'无有效期'}}</td><td>{{row.batch.receivedAt.slice(0,16).replace('T',' ')}}</td><td><span class="inv-status" :class="`inv-status-${row.status}`">{{row.status==='normal'?'正常':row.status==='near-expiry'?'临期':'过期'}}</span></td><td class="quantity">{{q(row.quantityMilli)}} {{row.sku?.baseUnitName}}</td><td class="money">{{actor.role==='sales-supervisor'?'—':money(row.amountCents)}}</td></tr></tbody></table></div></section></template>
